                    // Calculate visual status meter fills based on mock numbers
                    let progressPct = "60%";
                    let meterColor = "bg-cyan-400";
                    if (metric.label === "Latency") {
                      const val = parseInt(metric.value) || 2;
                      progressPct = val < 10 ? "95%" : val < 50 ? "85%" : val < 150 ? "60%" : "30%";
                      meterColor = "bg-amber-400";
                    } else if (metric.label === "Win Rate") {
                      const val = parseFloat(metric.value) || 50;
                      progressPct = `${val}%`;
                      meterColor = "bg-emerald-450";
                    } else if (metric.label === "Max Drawdown") {
                      const val = parseFloat(metric.value) || 20;
                      progressPct = `${100 - val * 4}%`;
                      meterColor = "bg-rose-455";
                    }

                    return (
                      <div key={i} className="bg-black/50 border border-zinc-900 rounded p-3 flex flex-col justify-between">
                        <span className="text-[8px] font-mono text-zinc-500 uppercase tracking-wider block mb-1">
                          {metric.label}
                        </span>
                        <span className="text-sm font-mono font-extrabold text-zinc-150">
                          {metric.value}
                        </span>
                        <div className="w-full h-[3px] bg-zinc-900 mt-2.5 rounded-full overflow-hidden">
                          <div className={`h-full ${meterColor}`} style={{ width: progressPct }} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Integrated features detailed block */}
              <div className="space-y-2.5">
                <span className="text-[9px] font-mono font-bold text-zinc-550 uppercase tracking-widest block">System Features Manifest</span>
                <div className="space-y-2">
                  {modalRelease.features.map((feature, i) => (
                    <div key={i} className="flex items-start gap-2.5 text-xs text-zinc-200 font-sans p-2 rounded bg-black/30 border border-zinc-900/60">
                      <ChevronRight className="h-4 w-4 text-cyan-400 flex-shrink-0 mt-0.5" />
                      <span>{feature}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Pagination Controls & Ledger Footer */}
            <div className="border-t border-zinc-850 pt-4 flex flex-col sm:flex-row justify-between items-center gap-4">
              <div className="flex items-center gap-2">
                <button 
                  onClick={handlePrevRelease}
                  className="px-3 py-1.5 bg-zinc-900 hover:bg-zinc-800 text-zinc-300 hover:text-zinc-50 border border-zinc-800 text-xs font-mono rounded cursor-pointer"
                >
                  &larr; PREV VERSION
                </button>
                <button 
                  onClick={handleNextRelease}
                  className="px-3 py-1.5 bg-zinc-900 hover:bg-zinc-800 text-zinc-300 hover:text-zinc-50 border border-zinc-800 text-xs font-mono rounded cursor-pointer"
                >
                  NEXT VERSION &rarr;
                </button>
              </div>

              <div className="text-[9px] font-mono text-zinc-500 text-right space-y-0.5">
                <div>LEDGER BLOCK HASH SIGNATURE</div>
                <div className="text-[#c5a85c] text-[8.5px]">GQR-MDL-{modalRelease.codename.toUpperCase().replace(' ', '-')}-2026</div>
              </div>
            </div>

          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { GQR_INDICATORS } from '../data/indicators';
import { PineIndicator } from '../types';
import { 
  Code2, 
  Terminal, 
  Copy, 
  Check, 
  Settings2, 
  BellRing, 
  Search, 
  Layers, 
  Hash,
  HelpCircle
} from 'lucide-react';

export default function IndicatorExplorer() {
  const [selectedInd, setSelectedInd] = useState<PineIndicator>(GQR_INDICATORS[0]);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState<string>('All');
  const [copied, setCopied] = useState(false);

  const categories = ['All', ...Array.from(new Set(GQR_INDICATORS.map(i => i.category)))];

  const filteredIndicators = GQR_INDICATORS.filter(ind => {
    const matchesSearch = ind.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          ind.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = activeCategory === 'All' || ind.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const handleCopy = () => {
    navigator.clipboard.writeText(selectedInd.code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 min-h-[calc(100vh-12rem)]" id="indicator-explorer">
      {/* Sidebar: Navigation List */}
      <div className="lg:col-span-4 bg-panel-dark border border-border-dark rounded-2xl p-4 flex flex-col gap-4">
        {/* Search header */}
        <div className="relative">
          <Search className="absolute left-3 top-2.5 h-4 w-4 text-zinc-500" />
          <input
            type="text"
            placeholder="Search premium indicators..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-[#050505]/45 border border-border-dark rounded-xl py-2 pl-9 pr-4 text-sm text-zinc-100 placeholder-zinc-500 focus:outline-none focus:border-brand-orange/50 focus:ring-1 focus:ring-brand-orange/20"
          />
        </div>

        {/* Categories Chips */}
        <div className="flex flex-wrap gap-1.5 pb-2 border-b border-border-medium">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium transition-all cursor-pointer ${
                activeCategory === cat
                  ? 'bg-brand-orange/10 text-brand-orange border border-brand-orange/35'
                  : 'bg-zinc-900 text-zinc-400 border border-border-dark hover:bg-zinc-800 hover:text-zinc-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Indicator list */}
        <div className="flex-1 overflow-y-auto max-h-[480px] lg:max-h-[600px] space-y-2 pr-1">
          {filteredIndicators.length > 0 ? (
            filteredIndicators.map(ind => (
              <button
                key={ind.id}
                onClick={() => {
                  setSelectedInd(ind);
                  setCopied(false);
                }}
                className={`w-full text-left p-3.5 rounded-xl border transition-all duration-200 flex flex-col gap-1.5 cursor-pointer ${
                  selectedInd.id === ind.id
                    ? 'bg-brand-orange/5 border-brand-orange/30 shadow-md shadow-brand-orange/10'
                    : 'bg-card-dark border-border-dark hover:bg-zinc-900/50 hover:border-border-medium'
                }`}
              >
                <div className="flex items-center justify-between">
                  <span className={`font-semibold text-sm transition-colors ${
                    selectedInd.id === ind.id ? 'text-brand-orange' : 'text-zinc-200'
                  }`}>
                    {ind.name}
                  </span>
                  <span className="text-[10px] uppercase font-mono tracking-wider text-zinc-555 px-1.5 py-0.5 rounded bg-zinc-950/20">
                    {ind.alerts.length > 0 ? 'Alerts' : 'No alerts'}
                  </span>
                </div>
                <p className="text-xs text-zinc-450 line-clamp-2 leading-relaxed">
                  {ind.description}
                </p>
                <div className="flex items-center gap-1.5 text-[10px] text-zinc-500 font-mono mt-1">
                  <Layers className="h-3 w-3" />
                  <span>{ind.category}</span>
