      {/* 100 Standards Interactive Catalog Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5">
        <AnimatePresence>
          {filteredQuestions.map((q) => {
            const isChecked = checkedIds.includes(q.id);
